package bad

import (
	"log/slog"
)

func testSlog() {
	password := "secret123"
	apiKey := "abc123"
	token := "xyz789"

	slog.Info("Server started")             // want `лог-сообщение должно начинаться со строчной буквы \(начинается с "S"\)`
	slog.Error("Failed to connect")         // want `лог-сообщение должно начинаться со строчной буквы \(начинается с "F"\)`
	slog.Info("привет мир")                 // want `лог-сообщение должно содержать только английские буквы \(найден символ "п"\)`
	slog.Error("ошибка")                    // want `лог-сообщение должно содержать только английские буквы \(найден символ "о"\)`
	slog.Info("server started!")            // want `лог-сообщение не должно заканчиваться на ! \? или \.\.\.`
	slog.Info("server started 😊")           // want `лог-сообщение не должно содержать эмодзи \(найден символ "😊"\)`
	slog.Error("failed!!")                  // want `лог-сообщение не должно заканчиваться на ! \? или \.\.\.`
	slog.Warn("loading...")                 // want `лог-сообщение не должно заканчиваться на ! \? или \.\.\.`
	slog.Info("user password: " + password) // want `лог-сообщение может содержать чувствительные данные: найдено ключевое слово "password"`
	slog.Debug("api_key=" + apiKey)         // want `лог-сообщение может содержать чувствительные данные: найдено ключевое слово "api_key" в префиксе`
	slog.Info("token: " + token)            // want `лог-сообщение может содержать чувствительные данные: найдено ключевое слово "token" в префиксе`
}
